def parse_signed_int(s):
    if not s:
        raise ValueError('empty string')
    sign = 1
    index = 0
    if s[0] == '+' or s[0] == '-':
        if s[0] == '-':
            sign = -1
            index = 1
        elif s[0] == '+':
            index = 1
    value = 0
    for ch in s[index:]:
